 h+='<div class="facts2" style="margin-bottom:14px"><div><small>Verified market value</small><b>'+(fx.mv?BA.inr(+fx.mv):'—')+'</b></div><div><small>Recommended fair price</small><b>'+(fx.fair?BA.inr(+fx.fair):'—')+'</b></div><div><small>Reserve price</small><b>'+BA.inr(p.reserve)+'</b></div><div><small>Verified</small><b>'+when+'</b></div></div>';
 if(fx.video)h+='<video controls preload="metadata" playsinline data-idb="'+ES(fx.video.k)+'" style="width:100%;border-radius:14px;background:#000;max-height:420px;margin-bottom:12px"></video>';
 if(lm.length)h+='<h3 style="font:800 15px var(--f);margin:6px 0">Prominent landmarks</h3><ul style="margin:0 0 12px;padding-left:18px">'+lm.map(function(x){return '<li>'+ES(x.km)+' km from '+ES(x.name)+'</li>'}).join('')+'</ul>';
 if(fx.pos||fx.neg)h+='<div class="pn"><div><h3>Positives</h3><ul>'+String(fx.pos||'—').split(/\n+/).filter(Boolean).map(function(x){return '<li>'+ES(x)+'</li>'}).join('')+'</ul></div><div><h3>Negatives</h3><ul>'+String(fx.neg||'—').split(/\n+/).filter(Boolean).map(function(x){return '<li>'+ES(x)+'</li>'}).join('')+'</ul></div></div>';
 if(fx.gps)h+='<p style="margin:0 0 12px"><b>GPS</b> '+ES(fx.gps)+(fx.maps?' · <a href="'+ES(fx.maps)+'" target="_blank" rel="noopener">Open in Google Maps ↗</a>':'')+'</p>';
 var docs=[].concat((fx.ec||[]).map(function(d,i){return {n:'Latest EC'+((fx.ec||[]).length>1?' · page '+(i+1):''),k:d.k,t:d.t}}),(fx.deed||[]).map(function(d,i){return {n:'Sale deed'+((fx.deed||[]).length>1?' · page '+(i+1):''),k:d.k,t:d.t}}),(fx.docs||[]).map(function(d){return {n:d.title,k:d.k,t:d.t}}));
 if(docs.length)h+='<h3 style="font:800 15px var(--f);margin:6px 0">Documents verified on site</h3>'+docs.map(function(d){return '<div class="doc"><span><b>'+ES(d.n)+'</b></span><a class="btn out sm" target="_blank" rel="noopener" data-idb="'+ES(d.k)+'" href="#">View ↗</a></div>'}).join('');
